svg.script:
// setClock(hh, mm)：游戏按游玩时间调用。下面的自动走时只用于单独打开本 SVG 预览（从 23:54 开始）。
var SEG = {0:'abcdef',1:'bc',2:'abged',3:'abgcd',4:'fgbc',5:'afgcd',6:'afgedc',7:'abc',8:'abcdefg',9:'abcdfg'};
function setClock(hh, mm) {
  var t = String(hh).padStart(2, '0') + String(mm).padStart(2, '0');
  for (var i = 0; i < 4; i++) 'abcdefg'.split('').forEach(function (s) {
    var el = document.getElementById('clk-' + i + '-' + s);
    if (el) el.style.display = SEG[+t[i]].indexOf(s) >= 0 ? '' : 'none';
  });
}
(function () {
  var start = Date.now(), base = 23 * 60 + 54;
  function tick() {
    var sec = Math.floor((Date.now() - start) / 1000), m = (base + Math.floor(sec / 60)) % 1440;
    setClock(Math.floor(m / 60), m % 60);
    var on = sec % 2 === 0 ? '' : 'none';
    document.getElementById('clk-colon-1').style.display = on;
    document.getElementById('clk-colon-2').style.display = on;
  }
  tick(); setInterval(tick, 500);
})();
